    def numTrees(self, n: int) -> int:
        def count_trees(nodes):
            if nodes <= 1:
                return 1
            total = 0
            for root in range(1, nodes + 1):
                left = count_trees(root - 1)  
                right = count_trees(nodes - root)  
                total += left * right
            return total

